pub const HELDOUT: &str = r1cs!("fixtures/heldout/HELDOUT-VECTORS.json");
pub const ADDENDUM: &str = r1cs!("EXPECTED-PACKET/ADDENDUM-1.json");

pub const REQ_INVOICE: &str = own!("requests/invoice-partial.request.json");
